import{_ as t,o as r,c as o,ah as a}from"./chunks/framework.CRsDMGp2.js";const m=JSON.parse('{"title":"Guide — Contributeur externe","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/contributeur-externe.md","filePath":"src/guide/contributeur-externe.md"}'),n={name:"guide/contributeur-externe.md"};function s(i,e,u,l,p,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="guide-—-contributeur-externe" tabindex="-1">Guide — Contributeur externe <a class="header-anchor" href="#guide-—-contributeur-externe" aria-label="Permalink to &quot;Guide — Contributeur externe&quot;">​</a></h1><p>Transmettre à Naia les demandes de votre pôle.</p><h2 id="bienvenue-sur-naia" tabindex="-1">Bienvenue sur Naia <a class="header-anchor" href="#bienvenue-sur-naia" aria-label="Permalink to &quot;Bienvenue sur Naia&quot;">​</a></h2><p>Vous faites partie d&#39;un pôle d&#39;edPage group — Commercial, Support, RH ou Facturation — et votre compte vous permet de transmettre vos demandes directement à Naia, sans passer par un e-mail ou un appel.</p><p>Votre accès est volontairement restreint : vous ne voyez que <strong>Mon espace</strong>, qui contient le formulaire de votre pôle et la liste de vos soumissions. Vous n&#39;accédez ni aux projets, ni aux documents, ni à la messagerie. Les recherches (client, projet, collaborateur) n&#39;affichent qu&#39;une référence et un nom.</p><h2 id="obtenir-son-compte" tabindex="-1">Obtenir son compte <a class="header-anchor" href="#obtenir-son-compte" aria-label="Permalink to &quot;Obtenir son compte&quot;">​</a></h2><p>Votre compte est créé par l&#39;administrateur de Naia, qui vous communique vos identifiants. À votre première connexion, changez votre mot de passe depuis <strong>Paramètres &gt; Sécurité</strong> (icône d&#39;engrenage en haut de l&#39;écran). Si vous quittez le pôle, l&#39;administrateur révoque votre accès.</p><h2 id="suivre-vos-soumissions" tabindex="-1">Suivre vos soumissions <a class="header-anchor" href="#suivre-vos-soumissions" aria-label="Permalink to &quot;Suivre vos soumissions&quot;">​</a></h2><p>La liste <strong>Mes soumissions</strong>, visible de vous seul, affiche chaque envoi avec son statut :</p><ul><li><strong>Envoyé</strong> : Naia a bien reçu votre soumission ; elle attend d&#39;être prise en charge ;</li><li><strong>Traité</strong> : son effet existe dans Naia — le projet est créé, la tâche est ajoutée, le collaborateur est affecté, ou le statut de paiement a été pris en compte.</li></ul><p>Vous n&#39;avez rien d&#39;autre à faire : une soumission passe à « Traité » d&#39;elle-même.</p><h2 id="pole-commercial" tabindex="-1">Pôle Commercial <a class="header-anchor" href="#pole-commercial" aria-label="Permalink to &quot;Pôle Commercial&quot;">​</a></h2><ul><li><strong>Nouveau projet</strong> : pour un client qui vient de signer, recherchez-le ou saisissez son nom s&#39;il est nouveau, choisissez le type de projet, puis <strong>Créer le projet</strong>. C&#39;est une demande : un administrateur la valide et désigne le chef de projet. Le projet reçoit alors sa référence (ex. <code>NAIA-0142</code>).</li><li><strong>Signaler un besoin dev</strong> : même formulaire que le pôle Support (ci-dessous). La tâche créée porte le badge <strong>Commercial</strong>.</li></ul><h2 id="pole-support" tabindex="-1">Pôle Support <a class="header-anchor" href="#pole-support" aria-label="Permalink to &quot;Pôle Support&quot;">​</a></h2><p><strong>Besoin de développement</strong> : quand un ticket révèle un besoin qui relève de l&#39;équipe de développement :</p><ol><li>indiquez la référence du ticket si vous en avez une (ex. <code>TCK-4821</code>) — elle est optionnelle ;</li><li>choisissez le projet concerné, ou <strong>Projet inconnu</strong> si vous ne savez pas de quel projet il s&#39;agit ;</li><li>décrivez le besoin, puis <strong>Envoyer vers Naia</strong>.</li></ol><p>Sur un projet connu, le besoin devient immédiatement une tâche du projet, avec le badge <strong>Support</strong>, et le chef de projet est notifié. Sur un projet inconnu, un administrateur choisit le bon projet avant de créer la tâche.</p><h2 id="pole-rh" tabindex="-1">Pôle RH <a class="header-anchor" href="#pole-rh" aria-label="Permalink to &quot;Pôle RH&quot;">​</a></h2><p>La liste <strong>Besoins de staffing en attente</strong> regroupe les demandes de renfort des chefs de projet, avec le profil requis. Pour chacune, choisissez le collaborateur retenu parmi les comptes existants, puis <strong>Confirmer l&#39;affectation</strong> : il rejoint automatiquement l&#39;équipe du projet, et le chef de projet est notifié.</p><p>Une ligne confirmée disparaît pour tous les comptes RH : deux personnes du pôle ne peuvent pas traiter le même besoin. Si la personne retenue n&#39;a pas encore de compte Naia (un expert externe, par exemple), demandez d&#39;abord à l&#39;administrateur de le créer.</p><p>Vous êtes notifié, dans l&#39;application et par e-mail, à chaque nouveau besoin de renfort.</p><h2 id="pole-facturation" tabindex="-1">Pôle Facturation <a class="header-anchor" href="#pole-facturation" aria-label="Permalink to &quot;Pôle Facturation&quot;">​</a></h2><p>La liste <strong>Jalons facturables signalés</strong> affiche chaque jalon facturable validé sur un projet, avec le montant transmis par Naia. Pour chacun, indiquez le <strong>statut de paiement</strong>, puis <strong>Mettre à jour le statut</strong> :</p><ul><li><strong>À jour</strong> : le paiement est réglé ; le jalon quitte votre liste ;</li><li><strong>En retard</strong> : la Direction et l&#39;administrateur sont alertés et décident de bloquer ou non le projet. Le jalon reste dans votre liste : quand le paiement est régularisé, repassez-le <strong>À jour</strong> pour permettre le déblocage.</li></ul><p>Vous êtes notifié, dans l&#39;application et par e-mail, à chaque nouveau jalon facturable. Aucune donnée comptable n&#39;est stockée dans Naia : vous ne faites qu&#39;y indiquer un statut.</p>',25)])])}const h=t(n,[["render",s]]);export{m as __pageData,h as default};
